            this._writeField(sp, "bezopt_sample", "x", x);
            this._writeField(sp, "bezopt_sample", "y", y);
            this._writeField(sp, "bezopt_sample", "nx", nx);
            this._writeField(sp, "bezopt_sample", "ny", ny);
