      this._writeField(cp, "bezopt_chain", "control_xy", controlPtr);
      this._writeField(cp, "bezopt_chain", "control_point_count", pointsInput.length);
      this._writeField(cp, "bezopt_chain", "samples", samplePtr);
      this._writeField(cp, "bezopt_chain", "sample_count", sampleCount);
      this._writeField(cp, "bezopt_chain", "left_region",
        this._integer(chainInput.left_region, `${label}.left_region`, 0, regionCount - 1));
      this._writeField(cp, "bezopt_chain", "right_region",
        this._integer(chainInput.right_region, `${label}.right_region`, 0, regionCount - 1));
      this._writeField(cp, "bezopt_chain", "closed", closed ? 1 : 0);
      this._writeField(cp, "bezopt_chain", "corner_knots", cornerPtr);
      this._writeField(cp, "bezopt_chain", "corner_knot_count", cornerCount);
