          sweeps: this._readField(reportPtr, "bezopt_report", "sweeps"),
          blocks_optimized: this._readField(reportPtr, "bezopt_report", "blocks_optimized"),
          function_evaluations: this._readField(reportPtr, "bezopt_report", "function_evaluations"),
          sample_evaluations: this._readField(reportPtr, "bezopt_report", "sample_evaluations"),
          topology_rejections: this._readField(reportPtr, "bezopt_report", "topology_rejections"),
          initial_energy: this._readField(reportPtr, "bezopt_report", "initial_energy"),
          final_energy: this._readField(reportPtr, "bezopt_report", "final_energy"),
          initial_normal_rmse_px: this._readField(reportPtr, "bezopt_report", "initial_normal_rmse_px"),
          final_normal_rmse_px: this._readField(reportPtr, "bezopt_report", "final_normal_rmse_px"),
          elapsed_ms: this._readField(reportPtr, "bezopt_report", "elapsed_ms"),
          converged: !!this._readField(reportPtr, "bezopt_report", "converged"),
