    keepalive.push({ free: () => this._free(viewPtr) });
    this._writeField(viewPtr, "bezopt_raster_view", "labels", labelPtr);
    this._writeField(viewPtr, "bezopt_raster_view", "width", width);
    this._writeField(viewPtr, "bezopt_raster_view", "height", height);
    this._writeField(viewPtr, "bezopt_raster_view", "label_row_stride", width);
    this._writeField(viewPtr, "bezopt_raster_view", "region_count", regionCount);
    this._writeField(viewPtr, "bezopt_raster_view", "region_linear_rgb", colorPtr);
    this._writeField(viewPtr, "bezopt_raster_view", "region_color_stride", 3);
    this._writeField(viewPtr, "bezopt_raster_view", "source_srgb8", sourcePtr);
    this._writeField(viewPtr, "bezopt_raster_view", "source_srgb_row_stride_bytes", sourceStride);
    this._writeField(viewPtr, "bezopt_raster_view", "optimized_region_rgb", 0);
    this._writeField(viewPtr, "bezopt_raster_view", "optimized_region_color_stride", 0);
