          status: this._readField(resultPtr, "bezopt_raster_report", "status"),
          status_text: statusText,
          subpixel_samples: this._readField(resultPtr, "bezopt_raster_report", "subpixel_samples"),
          cubic_tests: this._readField(resultPtr, "bezopt_raster_report", "cubic_tests"),
          crossings,
          transition_errors: transitionErrors,
          bands: this._readField(resultPtr, "bezopt_raster_report", "bands"),
          initial_length_px: this._readField(resultPtr, "bezopt_raster_report", "initial_length_px"),
          squared_error: this._readField(resultPtr, "bezopt_raster_report", "squared_error"),
          yang_data_energy: this._readField(resultPtr, "bezopt_raster_report", "yang_data_energy"),
          mse: this._readField(resultPtr, "bezopt_raster_report", "mse"),
