      this._writeField(viewPtr, "bezopt_svg_view", "width", width);
      this._writeField(viewPtr, "bezopt_svg_view", "height", height);
      this._writeField(viewPtr, "bezopt_svg_view", "region_count", regionCount);
      this._writeField(viewPtr, "bezopt_svg_view", "region_srgb", colorPtr);
      this._writeField(viewPtr, "bezopt_svg_view", "region_color_stride", 3);
      this._writeField(viewPtr, "bezopt_svg_view", "region_touches_frame", touchesPtr);

