          status: this._readField(resultPtr, "bezopt_svg_report", "status"),
          status_text: statusText,
          region_count: this._readField(resultPtr, "bezopt_svg_report", "region_count"),
          loop_count: this._readField(resultPtr, "bezopt_svg_report", "loop_count"),
          path_count: this._readField(resultPtr, "bezopt_svg_report", "path_count"),
